export class DeliveryLedger {
 async reserve(message: Envelope): Promise<Reservation> {
  const key = digest(message.destination, message.eventId);
  return this.store.insertUnlessPresent(key);
 }
 async complete(key: string) { await this.store.markComplete(key); }
}

