func PublishCompactedSegment(next *os.File, livePath string) error {
 if err := next.Sync(); err != nil { return err }
 if err := next.Close(); err != nil { return err }
 if err := os.Rename(next.Name(), livePath); err != nil { return err }
 return syncParent(livePath)
}

