public void replace(Collection<Rule> rules, long revision) {
 PolicySnapshot next = validator.buildSnapshot(rules, revision);
 PolicySnapshot prior = current.get();
 if (revision <= prior.revision()) throw new StaleRevisionException(revision);
 current.set(next);
}

